    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fab.letter_height_inches, oversize, loading]);

  if (loading) {
    return (
      <div className="rounded-xl p-4 text-center text-slate-500">
        Loading material library…
      </div>
